layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="pitch"] { color: rgb(187, 187, 187); border-left: 4px solid rgb(221, 221, 221); border-radius: 0px; font-family: posts, global, "pingfang sc", "microsoft yahei", sans-serif; font-size: 18px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(187, 187, 187); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 15px; padding-bottom: 0px; padding-left: 15px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 0px; box-shadow: rgba(0, 0, 0, 0.12) 0px 2px 2px 0px, rgba(0, 0, 0, 0.06) 0px 3px 1px -2px, rgba(0, 0, 0, 0.12) 0px 1px 5px 0px; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); background-color: rgb(34, 34, 34); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); background-color: rgb(85, 85, 85); border-radius: 0px; box-shadow: rgba(0, 0, 0, 0) 0px 0px 1px 0px; font-family: var(--ryt-font-body); font-size: 13px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 5px; padding-right: 20px; padding-bottom: 5px; padding-left: 20px; transition: background-color 0.2s ease-in-out }
[data-ryt="button"] { color: rgb(255, 255, 255); background-color: rgb(34, 34, 34); border-radius: 5px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 2.692; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 255, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-bottom: 1px solid var(--ryt-muted); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="review"] { color: var(--ryt-text); font-family: posts, global, "pingfang sc", "microsoft yahei", sans-serif; font-size: 18px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: posts, global, "pingfang sc", "microsoft yahei", sans-serif; font-size: 13.5px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; padding-bottom: 6px; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 27px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a::before { content: ""; display: block; position: absolute; width: 100%; height: 2px; color: var(--ryt-text); background-color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 27px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.2s ease-in-out; -webkit-text-fill-color: var(--ryt-text); bottom: 0px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { border-bottom-color: #eee; color: #eee }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { border-bottom-color: #eee; color: #eee }
[data-ryt="button"]:hover { color: rgb(252, 100, 35); opacity: 1 }
[data-ryt="nav"] a:hover { border-bottom-color: #eee; color: #eee }
